package render

import("strings";"testing";"github.com/TimUx/Doku-Wiki-Confluence_migration/internal/model")
func TestConfluenceStorageRendersPageIncludesAsNativeMacro(t *testing.T){p:=model.Page{ID:"server:backup",Nodes:[]model.Node{{Type:"heading",Level:"2",Text:"Backup"},{Type:"include",Target:"server:restore",Meta:map[string]string{"mode":"page"}}},Includes:[]model.Reference{{Target:"server:restore",Kind:"page"}}};got:=ConfluenceStorage(p);if !strings.Contains(got,"<ac:structured-macro ac:name=\"include\">"){t.Fatalf("include macro missing: %s",got)};if !strings.Contains(got,"<ri:page ri:content-title=\"restore\"/>"){t.Fatalf("include target missing: %s",got)};if strings.Contains(got,"[DOKUWIKI INCLUDE"){t.Fatalf("page include must not remain a placeholder: %s",got)};if !strings.Contains(got,"<ac:structured-macro ac:name=\"toc\"/>"){t.Fatalf("toc macro missing: %s",got)}}
func TestConfluenceStoragePreservesNonPageIncludePlaceholder(t *testing.T){p:=model.Page{ID:"server:backup",Nodes:[]model.Node{{Type:"include",Target:"server:restore",Meta:map[string]string{"mode":"section"}}}};got:=ConfluenceStorage(p);if !strings.Contains(got,"[DOKUWIKI INCLUDE section: server:restore]"){t.Fatalf("non-page include placeholder missing: %s",got)};if strings.Contains(got,"ac:name=\"include\""){t.Fatalf("section include must not be guessed as page include: %s",got)}}
func TestConfluencePageTitleFromDokuWikiID(t *testing.T){if got:=confluencePageTitle("2.2.3:kng_switche_-_service_beschreibung");got!="kng switche - service beschreibung"{t.Fatalf("unexpected title: %q",got)}}
func TestAttachmentNamesCollisionIsDeterministic(t *testing.T){p:=model.Page{Media:[]model.Reference{{Target:"one:image.png"},{Target:"two:image.png"}}};got:=AttachmentNames(p);if got["one:image.png"]!="image.png"||got["two:image.png"]!="image_2.png"{t.Fatalf("unexpected names: %#v",got)}}
func TestConfluenceStorageRendersExternalAndSamePageLinks(t *testing.T){p:=model.Page{ID:"storage:security",Nodes:[]model.Node{{Type:"heading",Level:"2",Text:"Datensicherheit"},{Type:"paragraph",Text:`[[https://example.com/security.pdf|Security PDF]] [[#datensicherheit|Zum Abschnitt]] [[storage:other|Andere Seite]]`}}};got:=ConfluenceStorage(p);if !strings.Contains(got,"<a href=\"https://example.com/security.pdf\">Security PDF</a>"){t.Fatalf("external link missing: %s",got)};if !strings.Contains(got,"<a href=\"#datensicherheit\">Zum Abschnitt</a>"){t.Fatalf("same-page link missing: %s",got)};if !strings.Contains(got,"[DOKUWIKI LINK: storage:other]"){t.Fatalf("internal-page placeholder missing: %s",got)}}
func TestPreviewRendersNestedMediaLink(t *testing.T){p:=model.Page{ID:"cc33:storage:howto:block:pure:active-cluster",Nodes:[]model.Node{{Type:"paragraph",Text:`[[https://example.com/wiki/lib/exe/detail.php/cc33:storage:howto:block:pure:pod_1.png|{{https://example.com/wiki/lib/exe/fetch.php/cc33:storage:howto:block:pure:pod_1.png?400}}]]`}}};got:=PreviewHTML(p);if strings.Contains(got,"[[https://"){t.Fatalf("raw wiki link remains: %s",got)};if !strings.Contains(got,"<a href=\"https://example.com/wiki/lib/exe/detail.php/cc33:storage:howto:block:pure:pod_1.png\""){t.Fatalf("image detail link missing: %s",got)};if !strings.Contains(got,"/api/media?target=cc33%3Astorage%3Ahowto%3Ablock%3Apure%3Apod_1.png"){t.Fatalf("media endpoint target missing: %s",got)}}
func TestWrapMapsToNativeConfluenceMacros(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"wrap",Plugin:"wrap",Meta:map[string]string{"kind":"info"},Children:[]model.Node{{Type:"paragraph",Text:"Information"}}},{Type:"wrap",Plugin:"wrap",Meta:map[string]string{"kind":"spoiler"},Children:[]model.Node{{Type:"paragraph",Text:"Geheimer Inhalt"}}},{Type:"wrap",Plugin:"wrap",Meta:map[string]string{"kind":"box"},Children:[]model.Node{{Type:"paragraph",Text:"Box"}}}}};got:=ConfluenceStorage(p);for _,want:=range []string{"ac:name=\"info\"","ac:name=\"expand\"","ac:name=\"panel\""}{if !strings.Contains(got,want){t.Fatalf("macro %s missing: %s",want,got)}}}
func TestNoTocControlSuppressesGeneratedToc(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"control",Plugin:"notoc"},{Type:"heading",Level:"2",Text:"Ohne TOC"}}};got:=ConfluenceStorage(p);if strings.Contains(got,"ac:name=\"toc\""){t.Fatalf("toc must be suppressed: %s",got)}}
func TestConfluenceStorageRendersNestedMixedLists(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"bullet_item",Text:"Parent A",Meta:map[string]string{"indent":"0"}},{Type:"bullet_item",Text:"Child A1",Meta:map[string]string{"indent":"1"}},{Type:"ordered_item",Text:"Child A2",Meta:map[string]string{"indent":"1"}},{Type:"ordered_item",Text:"Grandchild A2.1",Meta:map[string]string{"indent":"2"}},{Type:"bullet_item",Text:"Parent B",Meta:map[string]string{"indent":"0"}}}};got:=ConfluenceStorage(p);if !strings.Contains(got,"<ul><li>Parent A<ul><li>Child A1</li></ul><ol><li>Child A2<ol><li>Grandchild A2.1</li></ol></li></ol></li><li>Parent B</li></ul>"){t.Fatalf("nested list structure incorrect: %s",got)}}
func TestPreviewAndMarkdownPreserveListNesting(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"ordered_item",Text:"First",Meta:map[string]string{"indent":"0"}},{Type:"bullet_item",Text:"Nested",Meta:map[string]string{"indent":"1"}},{Type:"bullet_item",Text:"Nested again",Meta:map[string]string{"indent":"2"}},{Type:"ordered_item",Text:"Second",Meta:map[string]string{"indent":"0"}}}};preview:=PreviewHTML(p);if !strings.Contains(preview,"<ol><li>First<ul><li>Nested<ul><li>Nested again</li></ul></li></ul></li><li>Second</li></ol>"){t.Fatalf("preview nesting incorrect: %s",preview)};md:=Markdown(p);want:="1. First\n  - Nested\n    - Nested again\n2. Second\n";if md!=want{t.Fatalf("markdown nesting incorrect: %q",md)}}
func TestAllRenderersPreserveMixedNestedListTypes(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"bullet_item",Text:"Bullet parent",Meta:map[string]string{"indent":"0"}},{Type:"ordered_item",Text:"Number child",Meta:map[string]string{"indent":"1"}},{Type:"bullet_item",Text:"Bullet grandchild",Meta:map[string]string{"indent":"2"}},{Type:"bullet_item",Text:"Bullet child sibling",Meta:map[string]string{"indent":"1"}},{Type:"ordered_item",Text:"Number child sibling",Meta:map[string]string{"indent":"1"}},{Type:"bullet_item",Text:"Bullet parent 2",Meta:map[string]string{"indent":"0"}}}};preview:=PreviewHTML(p);wantPreview:="<ul><li>Bullet parent<ol><li>Number child<ul><li>Bullet grandchild</li></ul></li></ol><ul><li>Bullet child sibling</li></ul><ol><li>Number child sibling</li></ol></li><li>Bullet parent 2</li></ul>";if !strings.Contains(preview,wantPreview){t.Fatalf("mixed preview nesting incorrect: %s",preview)};md:=Markdown(p);wantMD:="- Bullet parent\n  1. Number child\n    - Bullet grandchild\n  - Bullet child sibling\n  1. Number child sibling\n- Bullet parent 2\n";if md!=wantMD{t.Fatalf("mixed markdown nesting incorrect: %q",md)};storage:=ConfluenceStorage(p);wantStorage:="<ul><li>Bullet parent<ol><li>Number child<ul><li>Bullet grandchild</li></ul></li></ol><ul><li>Bullet child sibling</li></ul><ol><li>Number child sibling</li></ol></li><li>Bullet parent 2</li></ul>";if !strings.Contains(storage,wantStorage){t.Fatalf("mixed storage nesting incorrect: %s",storage)}}
func TestAllRenderersSupportDeepListIndentation(t *testing.T){p:=model.Page{ID:"demo",Nodes:[]model.Node{{Type:"ordered_item",Text:"Level 0",Meta:map[string]string{"indent":"0"}},{Type:"bullet_item",Text:"Level 1",Meta:map[string]string{"indent":"1"}},{Type:"ordered_item",Text:"Level 2",Meta:map[string]string{"indent":"2"}},{Type:"bullet_item",Text:"Level 3",Meta:map[string]string{"indent":"3"}},{Type:"ordered_item",Text:"Level 4",Meta:map[string]string{"indent":"4"}},{Type:"ordered_item",Text:"Level 0 again",Meta:map[string]string{"indent":"0"}}}};preview:=PreviewHTML(p);if !strings.Contains(preview,"<ol><li>Level 0<ul><li>Level 1<ol><li>Level 2<ul><li>Level 3<ol><li>Level 4</li></ol></li></ul></li></ul></li><li>Level 0 again</li></ol>"){t.Fatalf("deep preview nesting incorrect: %s",preview)};md:=Markdown(p);want:="1. Level 0\n  - Level 1\n    1. Level 2\n      - Level 3\n        1. Level 4\n2. Level 0 again\n";if md!=want{t.Fatalf("deep markdown nesting incorrect: %q",md)};storage:=ConfluenceStorage(p);if !strings.Contains(storage,"<ol><li>Level 0<ul><li>Level 1<ol><li>Level 2<ul><li>Level 3<ol><li>Level 4</li></ol></li></ul></li></ul></li><li>Level 0 again</li></ol>"){t.Fatalf("deep storage nesting incorrect: %s",storage)}}
